const { sbRequest } = require('/home/node/scripts/cvpro-helpers.js');
const { broadcastId, templateName, audienceFilter } = $input.first().json.body;
let query = `/rest/v1/customers?select=id,phone_number&phone_number=not.is.null`;
if (audienceFilter?.lead_stage) query += `&lead_stage=eq.${audienceFilter.lead_stage}`;
const customers = await sbRequest($http, 'GET', query);
const templates = await sbRequest($http, 'GET', `/rest/v1/templates?name=eq.${templateName}&limit=1`);
const messageBody = templates?.[0]?.content || '';
let sent = 0, failed = 0;
for (const cust of customers || []) {
  try {
    await $http.request({
      method: 'POST',
      url: `https://graph.facebook.com/v21.0/${process.env.WHATSAPP_PHONE_NUMBER_ID}/messages`,
      headers: { Authorization: `Bearer ${process.env.WHATSAPP_ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
      body: { messaging_product: 'whatsapp', to: cust.phone_number, type: 'text', text: { body: messageBody.replace('{{full_name}}', cust.full_name || 'عميلنا') } },
    });
    sent++;
  } catch (_) { failed++; }
  await new Promise((r) => setTimeout(r, 200));
}
if (broadcastId) {
  await sbRequest($http, 'PATCH', `/rest/v1/broadcasts?id=eq.${broadcastId}`, { status: 'completed', sent_count: sent, failed_count: failed });
}
return [{ json: { sent, failed } }];
